(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cleanup=()=>{},adapterPromise;
function stop(){cleanup();cleanup=()=>{}}
const currentLesson=()=>window.BoraCourses[0].lessons.find(l=>l.id===location.hash.split('/')[1]);
function mergeText(previous,next){return next.startsWith(previous)?next:previous+next}
function loadAdapter(){if(window.BoraLiveAdapters?.gemini)return Promise.resolve(window.BoraLiveAdapters.gemini);if(!adapterPromise)adapterPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/gemini-vendor.js';script.onload=()=>resolve(window.BoraLiveAdapters.gemini);script.onerror=()=>{adapterPromise=null;script.remove();reject(Error('Не удалось загрузить голосовой модуль. Обнови страницу.'))};document.head.append(script)});return adapterPromise}
function page(){const l=currentLesson();if(!l)return '<div class="panel"><h1>Выбери урок</h1><a href="#courses/pt">Программа обучения</a></div>';if(!window.BoraAccount.liveEnabled)return `<div class="narrow panel"><div class="eyebrow">Gemini Live · Скоро</div><h1>Живой разговор</h1><p>Здесь можно будет говорить с Bora вслух: слышать ответы, перебивать и задавать вопросы по-русски. Помощник будет учитывать тему урока и объяснять простыми словами.</p><div class="notice">Подключение ещё готовится. Как только режим будет готов, здесь появится кнопка начала разговора.</div><p>А пока потренируйся с Bora по репликам — голосом или текстом.</p><a class="btn" href="#practice/${esc(l.id)}">Открыть практику →</a></div>`;return `<div class="narrow"><a class="back" href="#practice/${esc(l.id)}">← Практика по репликам</a><div class="eyebrow">Живой разговор · Gemini Live</div><h1>${esc(l.title)}: поговорим?</h1><p>${esc(l.scene)}</p><div class="panel"><p>Говори по-бразильски. Можно перебивать, просить повторить и задавать вопросы по-русски. Начнём с коротких фраз по теме урока.</p><p class="small">Одна беседа — до четырёх минут. Наушники помогут избежать эха.</p><label class="live-consent"><input type="checkbox" id="live-consent"> Разрешаю передавать звук разговора в Google для работы голосового помощника.</label><div class="row"><button class="btn" id="live-start" disabled>Начать разговор</button><button class="btn alt" id="live-mute" disabled>Пауза микрофона</button><button class="btn alt" id="live-end" disabled>Завершить</button></div><p id="live-status" role="status" aria-live="polite">Микрофон включится только после нажатия «Начать разговор».</p><p id="live-time" class="small"></p><div id="live-transcript" aria-live="polite"></div><p class="small">Звук передаётся напрямую Google. В аккаунте сохраняется текстовая расшифровка, а не аудиозапись. Расшифровка может ошибаться; официальную оценку уровня и произношения этот режим не выставляет.</p></div></div>`}
function bind(u,save){const $=s=>document.querySelector(s),l=currentLesson();if(!l||!$('#live-start'))return;u.livePractice??={};const r=u.livePractice[l.id]??={messages:[],sessions:0,totalSeconds:0};let generation=0;let alive=true,ending=false,starting=false,transport=null,audio=null,request=null,startedAt=0,deadline=null,ticker=null,muted=false;const pending={user:'',assistant:''};
const status=text=>{if(alive)$('#live-status').textContent=text};
function paint(){if(!alive)return;$('#live-transcript').innerHTML=r.messages.map(m=>`<article class="card" style="margin-top:12px"><strong>${m.role==='user'?'Ты':'Bora'}</strong><p>${esc(m.content)}</p>${m.interrupted?'<span class="small">Реплика прервана</span>':''}</article>`).join('')+['user','assistant'].filter(role=>pending[role]).map(role=>`<p class="small"><strong>${role==='user'?'Ты':'Bora'}:</strong> ${esc(pending[role])}</p>`).join('')}
function flush(role,interrupted=false){const content=pending[role].trim().slice(0,2000);pending[role]='';if(content){r.messages.push({role,content,at:new Date().toISOString(),interrupted});r.messages=r.messages.slice(-24);save()}paint()}
function end(reason='Разговор завершён. Текст сохранён в аккаунте.'){if(ending)return;ending=true;generation++;request?.abort();clearTimeout(deadline);clearInterval(ticker);audio?.close();audio=null;const old=transport;transport=null;try{old?.close()}catch{}flush('user');flush('assistant');if(startedAt){r.sessions++;r.totalSeconds+=Math.min(240,Math.round((Date.now()-startedAt)/1000));r.lastSessionAt=new Date().toISOString();startedAt=0;save()}starting=false;if(alive){$('#live-start').disabled=!$('#live-consent').checked;$('#live-end').disabled=true;$('#live-mute').disabled=true;$('#live-mute').textContent='Пауза микрофона';status(reason)}}
function onEvent(e){if(!alive||ending)return;try{if(e.type==='audio')audio?.play(e.data,e.rate);if(e.type==='transcript'){pending[e.role]=mergeText(pending[e.role],e.text).slice(0,2400);if(e.finished)flush(e.role);else paint()}if(e.type==='interrupted'){audio?.clearPlayback();flush('assistant',true);status('Слушаю тебя…')}if(e.type==='turn-complete'){flush('user');flush('assistant');status('Твоя очередь. Можно говорить.')}if(e.type==='ending')status('Беседа скоро завершится. Можно закончить мысль.');if(e.type==='error')end('Связь с голосовым помощником прервалась. Текст сохранён; можно попробовать позже.');if(e.type==='closed')end()}catch{end('Не удалось воспроизвести ответ. Попробуй начать новую беседу позже.')}}
$('#live-consent').onchange=()=>{$('#live-start').disabled=!$('#live-consent').checked||starting||!!transport};
$('#live-start').onclick=async()=>{if(starting||transport||!$('#live-consent').checked)return;if(!window.BoraLiveAudio.supported()){status('Для живого разговора нужен браузер с доступом к микрофону, например актуальный Chrome или Edge.');return}const run=++generation;const runAlive=()=>alive&&!ending&&run===generation;ending=false;starting=true;muted=false;$('#live-start').disabled=true;$('#live-end').disabled=false;status('Подключаю разговор…');const requestController=new AbortController();request=requestController;try{const localAudio=window.BoraLiveAudio.create({onChunk:(data,rate)=>{if(runAlive()&&transport&&!muted){try{transport.sendAudio(data,rate)}catch{end('Соединение прервалось. Текст сохранён.')}}}});audio=localAudio;await localAudio.prepare();if(!runAlive()){localAudio.close();return}const response=await fetch('/api/live-session',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await window.BoraAccount.accessToken()},body:JSON.stringify({lessonId:l.id}),signal:AbortSignal.any([requestController.signal,AbortSignal.timeout(45000)])});const value=await response.json();if(!response.ok)throw Error(value.error||'Не удалось подключить беседу.');if(!runAlive())return;const adapter=await loadAdapter();if(!runAlive())return;const connected=await adapter.connect({token:value.token,model:value.model,onEvent:event=>{if(runAlive())onEvent(event)}});if(!runAlive()){connected.close();return}transport=connected;starting=false;startedAt=Date.now();const remaining=Math.max(0,Math.min(240000,Date.parse(value.endsAt)-Date.now()));if(!remaining){end('Время подключения истекло. Попробуй позже.');return}$('#live-mute').disabled=false;const finishAt=Date.now()+remaining;const tick=()=>{if(alive)$('#live-time').textContent='Осталось '+Math.max(0,Math.ceil((finishAt-Date.now())/1000))+' сек.'};tick();ticker=setInterval(tick,1000);deadline=setTimeout(()=>end('Четыре минуты прошли. Можно отдохнуть и продолжить позже.'),remaining);status('Можно говорить. Bora начнёт разговор по теме урока.');transport.sendText('Comece a conversa com uma saudação curta em português brasileiro e uma pergunta simples sobre a situação da lição.')}catch(e){if(runAlive())end(e.name==='NotAllowedError'?'Разреши доступ к микрофону. Можно вернуться к практике по репликам.':e.name==='AbortError'?'Подключение прервано. Попробуй позже.':e.message||'Не удалось подключиться.')}};
$('#live-end').onclick=()=>end();$('#live-mute').onclick=()=>{if(!transport)return;muted=!muted;audio.mute(muted);if(muted)transport.pauseInput();$('#live-mute').textContent=muted?'Включить микрофон':'Пауза микрофона';status(muted?'Микрофон на паузе.':'Микрофон включён. Можно говорить.')};const hide=()=>{if(document.hidden&&(transport||starting))end('Разговор остановлен, потому что вкладка скрыта. Текст сохранён.')};document.addEventListener('visibilitychange',hide);paint();cleanup=()=>{alive=false;end('');document.removeEventListener('visibilitychange',hide)};
}
window.BoraLivePractice={page,bind,stop,mergeText};
})();
